.plans{display:grid;grid-template-columns:repeat(auto-fit,minmax(250px,1fr));gap:16px;margin-top:22px}
.plan{background:#fff;border:1px solid var(--line);border-radius:18px;padding:22px;display:flex;flex-direction:column;gap:8px}
.plan-name{font-weight:900;font-size:20px;display:flex;gap:8px;align-items:center}.plan-desc{color:var(--muted);min-height:54px}
.plan-price{font-size:28px;font-weight:900}.plan-price small{font-size:13px;color:var(--muted);font-weight:600}
.plan-features{list-style:none;padding:0;margin:6px 0;line-height:2.1}.plan-features .no{color:#a0aec0}.muted{color:var(--muted)}.pill{font-size:12px}
.toggle{display:inline-flex;border:1px solid var(--line);border-radius:10px;overflow:hidden;background:#fff}.toggle a{padding:7px 14px;font-weight:700;text-decoration:none}.toggle a.on{background:var(--ink);color:#fff}
